// 컴파일된 Vue 컴포넌트 라이브러리 흉내(R189·R190 재현): render 함수 컴포넌트
// FButton·FCard·FIcon은 __file 없음(실제 Element Plus 배포본 모양 — name만 있다), FTag는 node_modules __file 유지(두 경우 모두 라이브러리로 분류돼야 한다)
import { defineComponent, h, Transition } from 'vue';

// FButton 내부 레이어 — 이름 있고 __file 없음. 이 안 요소를 찍어도 component는 사용자 템플릿에 직접 쓴 FButton이어야 한다(R190-b)
const FIcon = defineComponent({
  name: 'FIcon',
  render() { return h('span', { class: 'f-icon' }, '*'); },
});

export const FButton = defineComponent({
  name: 'FButton',
  render() { return h('button', { class: 'f-btn' }, [h(FIcon), this.$slots.default?.()]); },
});

export const FCard = defineComponent({
  name: 'FCard',
  render() { return h('div', { class: 'f-card' }, this.$slots.default?.()); },
});

// 내부에 <Transition>(Vue 내장: BaseTransition 인스턴스가 체인에 생긴다, __file 없음)을 둔다
export const FTag = defineComponent({
  name: 'FTag',
  __file: 'lib/node_modules/fake-vue-ui/FTag.vue',
  render() { return h(Transition, null, { default: () => h('span', { class: 'f-tag' }, this.$slots.default?.()) }); },
});
